#!/usr/bin/env python3
from pathlib import Path
import base64,gzip,hashlib,subprocess,sys,tempfile,json
PAYLOAD=""
PATCH_SHA="70f9376294cbcda20b409067407111cff18ba764cc5c6a409d99f8865af9d1e4"
def main():
    if len(sys.argv)!=2: raise SystemExit("Usage: apply.py <exact-1.0.0-source>")
    root=Path(sys.argv[1]).resolve(strict=True)
    patch=gzip.decompress(base64.b64decode(PAYLOAD))
    assert hashlib.sha256(patch).hexdigest()==PATCH_SHA
    with tempfile.NamedTemporaryFile(suffix=".patch") as f:
        f.write(patch);f.flush()
        cmd=["git","apply","--recount","--whitespace=error","--directory="+root.name]
        subprocess.run(cmd+["--check",f.name],cwd=root.parent,check=True)
        subprocess.run(cmd+[f.name],cwd=root.parent,check=True)
    evidence=root.parent/"evidence";evidence.mkdir(exist_ok=True)
    (evidence/"simple-create-101.patch").write_bytes(patch)
    print(json.dumps({"schema":"territory-simple-create-101","patchSha256":PATCH_SHA,"version":"1.0.1","phase7Reopened":False,"ux":"New Territory -> choose type -> add map -> create -> preview -> save","singleCompleteUserMapCanBeAuthoritative":True},indent=2))
if __name__=="__main__": main()
